export const chartStyle='<style>.kana-chart-head{flex-wrap:nowrap;gap:12px;align-items:center;padding-bottom:0}.kana-chart-head #panel-title{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.kana-chart-head .kana-chart-tabs{display:flex;flex-flow:row nowrap;flex:1;width:auto;gap:16px;margin:0;position:relative}.kana-chart-head .kana-chart-tabs button{flex:1;min-width:0;min-height:52px;margin:0;padding:12px 0;background:transparent;color:var(--ink);border:0;border-bottom:2px solid transparent;border-radius:0;font-size:calc(16px * var(--text-scale));opacity:.55;transition:opacity .2s ease;transform:none;box-shadow:none;-webkit-tap-highlight-color:transparent}.kana-chart-head .kana-chart-tabs button[aria-selected=true]{opacity:1;font-weight:700}.kana-chart-tabs:after{content:"";position:absolute;bottom:0;left:0;width:calc((100% - 16px)/2);height:2px;background:var(--ink);transform:translateX(0);transition:transform .22s ease}.kana-chart-tabs[data-selected=katakana]:after{transform:translateX(calc(100% + 16px))}[data-motion=off] .kana-chart-tabs:after{transition:none}@media(prefers-reduced-motion:reduce){.kana-chart-tabs:after,.kana-chart-head .kana-chart-tabs button{transition:none}}.kana-chart-head .icon-button{flex:none;transition:none;-webkit-tap-highlight-color:transparent}.kana-reference{width:100%;table-layout:fixed;border-collapse:collapse;margin:0 0 24px}.kana-reference caption{text-align:left;font-weight:700;margin:0 0 12px;color:var(--ink)}.kana-reference td{height:66px;text-align:center;border:1px solid var(--paper-line);padding:6px 2px}.kana-reference td>span{display:block;font-size:calc(24px * var(--text-scale));line-height:1.4}.kana-reference small{display:block;font-size:calc(12px * var(--text-scale));color:var(--ink);opacity:.75}</style>';
